473|static int unpack_object(scanner_t *s, json_t *root, va_list *ap) {
474|    int ret = -1;
475|    int strict = 0;
476|    int gotopt = 0;
477|
478|    /* Use a set (emulated by a hashtable) to check that all object
479|       keys are accessed. Checking that the correct number of keys
480|       were accessed is not enough, as the same key can be unpacked
481|       multiple times.
482|    */
483|    hashtable_t key_set;
484|
485|    if (hashtable_init(&key_set)) {
486|        set_error(s, "<internal>", json_error_out_of_memory, "Out of memory");
487|        return -1;
488|    }
489|
490|    if (root && !json_is_object(root)) {
491|        set_error(s, "<validation>", json_error_wrong_type, "Expected object, got %s",
492|                  type_name(root));
493|        goto out;
494|    }
495|    next_token(s);
496|
497|    while (token(s) != '}') {
498|        const char *key;
499|        size_t key_len;
500|        json_t *value;
501|        int opt = 0;
502|
503|        if (strict != 0) {
504|            set_error(s, "<format>", json_error_invalid_format,
505|                      "Expected '}' after '%c', got '%c'", (strict == 1 ? '!' : '*'),
506|                      token(s));
507|            goto out;
508|        }
509|
510|        if (!token(s)) {
511|            set_error(s, "<format>", json_error_invalid_format,
512|                      "Unexpected end of format string");
513|            goto out;
514|        }
515|
516|        if (token(s) == '!' || token(s) == '*') {
517|            strict = (token(s) == '!' ? 1 : -1);
518|            next_token(s);
519|            continue;
520|        }
521|
522|        if (token(s) != 's') {
523|            set_error(s, "<format>", json_error_invalid_format,
524|                      "Expected format 's', got '%c'", token(s));
525|            goto out;
526|        }
527|
528|        key = va_arg(*ap, const char *);
529|        if (!key) {
530|            set_error(s, "<args>", json_error_null_value, "NULL object key");
531|            goto out;
532|        }
533|        key_len = strlen(key);
534|
535|        next_token(s);
536|
537|        if (token(s) == '?') {
538|            opt = gotopt = 1;
539|            next_token(s);
540|        }
541|
542|        if (!root) {
543|            /* skipping */
544|            value = NULL;
545|        } else {
546|            value = json_object_getn(root, key, key_len);
547|            if (!value && !opt) {
548|                set_error(s, "<validation>", json_error_item_not_found,
549|                          "Object item not found: %s", key);
550|                goto out;
551|            }
552|        }
553|
554|        if (unpack(s, value, ap))
555|            goto out;
556|
557|        hashtable_set(&key_set, key, key_len, json_null());
558|        next_token(s);
559|    }
560|
561|    if (strict == 0 && (s->flags & JSON_STRICT))
562|        strict = 1;
563|
564|    if (root && strict == 1) {
565|        /* We need to check that all non optional items have been parsed */
566|        const char *key;
567|        size_t key_len;
568|        /* keys_res is 1 for uninitialized, 0 for success, -1 for error. */
569|        int keys_res = 1;
570|        strbuffer_t unrecognized_keys;
571|        json_t *value;
572|        long unpacked = 0;
573|
574|        if (gotopt || json_object_size(root) != key_set.size) {
575|            json_object_keylen_foreach(root, key, key_len, value) {
576|                if (!hashtable_get(&key_set, key, key_len)) {
577|                    unpacked++;
578|
579|                    /* Save unrecognized keys for the error message */
580|                    if (keys_res == 1) {
581|                        keys_res = strbuffer_init(&unrecognized_keys);
582|                    } else if (!keys_res) {
583|                        keys_res = strbuffer_append_bytes(&unrecognized_keys, ", ", 2);
584|                    }
585|
586|                    if (!keys_res)
587|                        keys_res =
588|                            strbuffer_append_bytes(&unrecognized_keys, key, key_len);
589|                }
590|            }
591|        }
592|        if (unpacked) {
593|            set_error(s, "<validation>", json_error_end_of_input_expected,
594|                      "%li object item(s) left unpacked: %s", unpacked,
595|                      keys_res ? "<unknown>" : strbuffer_value(&unrecognized_keys));
596|            strbuffer_close(&unrecognized_keys);
597|            goto out;
598|        }
599|    }
600|
601|    ret = 0;
602|
603|out:
604|    hashtable_close(&key_set);
605|    return ret;
606|}

